styles:
@font-face{ font-family:"Manrope";src:url("https://www.dgeniussolutions.com/wp-content/cache/fonts/1/google-fonts/fonts/s/manrope/v20/xn7gYHE41ni1AdIRggexSg.woff2") format("woff2");font-weight:100 900;font-style:normal;font-display:swap; }
@font-face{ font-family:"Space Grotesk";src:url("https://www.dgeniussolutions.com/wp-content/cache/fonts/1/google-fonts/fonts/s/spacegrotesk/v22/V8mDoQDjQSkFtoMM3T6r8E7mPbF4Cw.woff2") format("woff2");font-weight:300 700;font-style:normal;font-display:swap; }

/* Final hard override: AI Production portfolio tabs.
   Prevent Elementor/theme/global button gradients from hijacking inactive tabs. */
.dgs-ai-ads-page #ai-production-portfolio .dgs-ai-portfolio-tabs,
.dgs-ai-ads-page .dgs-ai-portfolio-tabs {
  background: transparent !important;
  background-image: none !important;
}

.dgs-ai-ads-page #ai-production-portfolio .dgs-ai-portfolio-tabs .dgs-ai-tab,
.dgs-ai-ads-page .dgs-ai-portfolio-tabs .dgs-ai-tab,
.dgs-ai-ads-page .dgs-ai-portfolio-tabs button.dgs-ai-tab,
.dgs-ai-ads-page button.dgs-ai-tab:not(.active) {
  appearance: none !important;
  -webkit-appearance: none !important;
  background: #ffffff !important;
  background-color: #ffffff !important;
  background-image: none !important;
  background-size: auto !important;
  color: #5e5a66 !important;
  -webkit-text-fill-color: #5e5a66 !important;
  border: 1px solid rgba(20,17,31,.14) !important;
  box-shadow: 0 10px 24px rgba(20,17,31,.05) !important;
  text-shadow: none !important;
  filter: none !important;
  opacity: 1 !important;
}

.dgs-ai-ads-page #ai-production-portfolio .dgs-ai-portfolio-tabs .dgs-ai-tab::before,
.dgs-ai-ads-page #ai-production-portfolio .dgs-ai-portfolio-tabs .dgs-ai-tab::after,
.dgs-ai-ads-page .dgs-ai-portfolio-tabs .dgs-ai-tab::before,
.dgs-ai-ads-page .dgs-ai-portfolio-tabs .dgs-ai-tab::after {
  content: none !important;
  display: none !important;
  background: none !important;
  background-image: none !important;
}

.dgs-ai-ads-page #ai-production-portfolio .dgs-ai-portfolio-tabs .dgs-ai-tab:hover,
.dgs-ai-ads-page .dgs-ai-portfolio-tabs .dgs-ai-tab:hover,
.dgs-ai-ads-page #ai-production-portfolio .dgs-ai-portfolio-tabs .dgs-ai-tab:focus,
.dgs-ai-ads-page .dgs-ai-portfolio-tabs .dgs-ai-tab:focus {
  background: #ffffff !important;
  background-color: #ffffff !important;
  background-image: none !important;
  color: #14111f !important;
  -webkit-text-fill-color: #14111f !important;
  border-color: rgba(196,63,122,.30) !important;
  outline: none !important;
  box-shadow: 0 14px 34px rgba(20,17,31,.08) !important;
}

.dgs-ai-ads-page #ai-production-portfolio .dgs-ai-portfolio-tabs .dgs-ai-tab.active,
.dgs-ai-ads-page .dgs-ai-portfolio-tabs .dgs-ai-tab.active,
.dgs-ai-ads-page #ai-production-portfolio .dgs-ai-portfolio-tabs button.dgs-ai-tab.active,
.dgs-ai-ads-page .dgs-ai-portfolio-tabs button.dgs-ai-tab.active {
  background: linear-gradient(135deg, #e8612a 0%, #c43f7a 50%, #6247b0 100%) !important;
  background-color: #c43f7a !important;
  background-image: linear-gradient(135deg, #e8612a 0%, #c43f7a 50%, #6247b0 100%) !important;
  color: #ffffff !important;
  -webkit-text-fill-color: #ffffff !important;
  border-color: transparent !important;
  box-shadow: 0 16px 38px rgba(196,63,122,.18) !important;
}

.dgs-ai-ads-page #ai-production-portfolio .dgs-ai-portfolio-tabs .dgs-ai-tab.active:hover,
.dgs-ai-ads-page .dgs-ai-portfolio-tabs .dgs-ai-tab.active:hover,
.dgs-ai-ads-page #ai-production-portfolio .dgs-ai-portfolio-tabs .dgs-ai-tab.active:focus,
.dgs-ai-ads-page .dgs-ai-portfolio-tabs .dgs-ai-tab.active:focus {
  background: linear-gradient(135deg, #e8612a 0%, #c43f7a 50%, #6247b0 100%) !important;
  background-image: linear-gradient(135deg, #e8612a 0%, #c43f7a 50%, #6247b0 100%) !important;
  color: #ffffff !important;
  -webkit-text-fill-color: #ffffff !important;
}

/* Stop Elementor/global button styling from leaking into lightbox controls too. */
.dgs-ai-ads-page .dgs-ai-lb-btn,
.dgs-ai-ads-page .dgs-ai-lb-btn:hover,
.dgs-ai-ads-page .dgs-ai-lb-btn:focus {
  background: rgba(18,18,24,.82) !important;
  background-color: rgba(18,18,24,.82) !important;
  background-image: none !important;
  color: #ffffff !important;
  -webkit-text-fill-color: #ffffff !important;
  border: 1px solid rgba(255,255,255,.24) !important;
}

.dgs-ai-ads-page,
.dgs-ai-ads-page * {
  box-sizing: border-box !important;
}

.dgs-ai-ads-page {
  --dgs-bg: #fbfaf7;
  --dgs-bg-soft: #f4f1ec;
  --dgs-card: #ffffff;
  --dgs-text: #14111f;
  --dgs-muted: #5e5a66;
  --dgs-soft: #85808f;
  --dgs-line: rgba(20,17,31,0.12);
  --dgs-line-strong: rgba(20,17,31,0.2);
  --dgs-orange: #e8612a;
  --dgs-rose: #c43f7a;
  --dgs-violet: #6247b0;
  --dgs-blue: #1179a8;
  --dgs-gradient: linear-gradient(135deg, #e8612a 0%, #c43f7a 50%, #6247b0 100%);
  --dgs-shadow: 0 24px 70px rgba(20,17,31,0.08);
  --dgs-shadow-strong: 0 34px 90px rgba(20,17,31,0.14);
  font-family: "Manrope", Arial, sans-serif !important;
  background:
    radial-gradient(circle at 8% 4%, rgba(232,97,42,.10), transparent 32%),
    radial-gradient(circle at 96% 12%, rgba(98,71,176,.12), transparent 30%),
    linear-gradient(180deg, #fbfaf7 0%, #f8f5ef 46%, #fbfaf7 100%) !important;
  color: var(--dgs-text) !important;
  overflow: hidden !important;
  line-height: 1.65 !important;
  width: 100vw !important;
  max-width: 100vw !important;
  margin-left: calc(50% - 50vw) !important;
  margin-right: calc(50% - 50vw) !important;
}

.dgs-ai-ads-page a {
  color: inherit !important;
  text-decoration: none !important;
}

.dgs-ai-wrap {
  width: min(1480px, calc(100% - 48px)) !important;
  margin: 0 auto !important;
}

.dgs-ai-section {
  padding: clamp(78px, 8vw, 140px) 0 !important;
  position: relative !important;
  z-index: 2 !important;
}

.dgs-ai-eyebrow {
  display: inline-flex !important;
  align-items: center !important;
  gap: 10px !important;
  color: var(--dgs-rose) !important;
  font-size: 12px !important;
  font-weight: 900 !important;
  letter-spacing: 2.7px !important;
  text-transform: uppercase !important;
  margin-bottom: 18px !important;
}

.dgs-ai-eyebrow::before {
  content: "" !important;
  width: 34px !important;
  height: 2px !important;
  background: var(--dgs-gradient) !important;
  border-radius: 999px !important;
}

.dgs-grad-text {
  background: var(--dgs-gradient) !important;
  background-size: 200% 100% !important;
  -webkit-background-clip: text !important;
  -webkit-text-fill-color: transparent !important;
  background-clip: text !important;
}

.dgs-ai-section-head {
  max-width: 900px !important;
  margin-bottom: 46px !important;
}

.dgs-ai-section-head.center {
  text-align: center !important;
  margin-left: auto !important;
  margin-right: auto !important;
}

.dgs-ai-section-head h2 {
  margin: 0 0 18px !important;
  color: var(--dgs-text) !important;
  font-size: clamp(34px, 5vw, 74px) !important;
  font-weight: 850 !important;
  line-height: 1.03 !important;
  letter-spacing: -0.06em !important;
}

.dgs-ai-section-head p {
  margin: 0 !important;
  color: var(--dgs-muted) !important;
  font-size: clamp(16px, 1.45vw, 20px) !important;
  line-height: 1.75 !important;
  max-width: 800px !important;
}

.dgs-ai-btn {
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  min-height: 54px !important;
  padding: 15px 24px !important;
  border-radius: 999px !important;
  font-weight: 900 !important;
  font-size: 14px !important;
  line-height: 1.1 !important;
  border: 1px solid rgba(20,17,31,.16) !important;
  transition: transform .22s ease, box-shadow .22s ease, border-color .22s ease !important;
  background-image: none !important;
}

.dgs-ai-btn-primary {
  background: var(--dgs-gradient) !important;
  background-image: var(--dgs-gradient) !important;
  color: #fff !important;
  border-color: transparent !important;
  box-shadow: 0 18px 45px rgba(196,63,122,.22) !important;
}

.dgs-ai-btn-ghost {
  background: #fff !important;
  color: var(--dgs-text) !important;
}

.dgs-ai-btn:hover {
  transform: translateY(-3px) !important;
}

.dgs-ai-hero {
  position: relative !important;
  min-height: 100vh !important;
  padding: clamp(92px, 8vw, 140px) 0 clamp(70px, 7vw, 110px) !important;
  display: flex !important;
  align-items: center !important;
}

.dgs-ai-hero::before {
  content: "" !important;
  position: absolute !important;
  inset: 7% -12% auto auto !important;
  width: 560px !important;
  height: 560px !important;
  border-radius: 999px !important;
  background: radial-gradient(circle, rgba(196,63,122,.12), transparent 68%) !important;
  pointer-events: none !important;
}

.dgs-ai-hero-grid {
  display: grid !important;
  grid-template-columns: minmax(0, 1.04fr) minmax(390px, .74fr) !important;
  gap: clamp(34px, 5vw, 76px) !important;
  align-items: start !important;
  position: relative !important;
  z-index: 2 !important;
}

.dgs-ai-hero h1 {
  color: var(--dgs-text) !important;
  margin: 0 0 24px !important;
  font-size: clamp(44px, 6.7vw, 104px) !important;
  line-height: .96 !important;
  letter-spacing: -0.07em !important;
  font-weight: 900 !important;
  max-width: 980px !important;
}

.dgs-ai-hero-sub {
  color: var(--dgs-muted) !important;
  font-size: clamp(17px, 1.55vw, 22px) !important;
  line-height: 1.75 !important;
  max-width: 820px !important;
  margin: 0 0 28px !important;
}

.dgs-ai-proof-row {
  display: grid !important;
  grid-template-columns: repeat(3, minmax(0, 1fr)) !important;
  gap: 14px !important;
  margin-top: 32px !important;
  max-width: 900px !important;
}

.dgs-ai-mini {
  background: rgba(255,255,255,.78) !important;
  border: 1px solid var(--dgs-line) !important;
  border-radius: 22px !important;
  padding: 18px !important;
  min-height: 110px !important;
  box-shadow: 0 18px 46px rgba(20,17,31,.055) !important;
}

.dgs-ai-mini strong {
  display: block !important;
  color: var(--dgs-text) !important;
  font-size: 20px !important;
  line-height: 1.1 !important;
  margin-bottom: 8px !important;
}

.dgs-ai-mini span {
  display: block !important;
  color: var(--dgs-muted) !important;
  font-size: 13px !important;
  line-height: 1.55 !important;
}

.dgs-ai-hero-note {
  margin-top: 22px !important;
  color: var(--dgs-soft) !important;
  max-width: 800px !important;
  font-size: 14px !important;
  line-height: 1.7 !important;
}

.dgs-ai-form-card {
  background: rgba(255,255,255,.96) !important;
  color: #101018 !important;
  border-radius: 32px !important;
  padding: clamp(22px, 2.4vw, 34px) !important;
  border: 1px solid rgba(20,17,31,.10) !important;
  box-shadow: var(--dgs-shadow-strong) !important;
  position: sticky !important;
  top: 110px !important;
  overflow: hidden !important;
}

.dgs-ai-form-card::before {
  content: "" !important;
  position: absolute !important;
  inset: 0 0 auto 0 !important;
  height: 5px !important;
  background: var(--dgs-gradient) !important;
}

.dgs-ai-form-card h2 {
  color: #101018 !important;
  margin: 4px 0 8px !important;
  font-size: clamp(24px, 2.1vw, 32px) !important;
  line-height: 1.15 !important;
  letter-spacing: -0.035em !important;
  font-weight: 900 !important;
}

.dgs-ai-form-card > p {
  color: #4d5161 !important;
  margin: 0 0 16px !important;
  font-size: 15px !important;
  line-height: 1.65 !important;
}

.dgs-ai-b2b-strip {
  border-radius: 18px !important;
  padding: 14px 16px !important;
  margin: 0 0 18px !important;
  background: linear-gradient(135deg, rgba(232,97,42,.09), rgba(196,63,122,.10)) !important;
  border: 1px solid rgba(196,63,122,.16) !important;
}

.dgs-ai-b2b-strip strong {
  display: block !important;
  color: #14131a !important;
  font-size: 14px !important;
  margin-bottom: 5px !important;
}

.dgs-ai-b2b-strip span {
  display: block !important;
  color: #565b68 !important;
  font-size: 13px !important;
  line-height: 1.5 !important;
}

.dgs-ai-form-slot {
  width: 100% !important;
}

/* Fluent Forms hard override */
.dgs-ai-ads-page .ff-el-group,
.dgs-ai-ads-page .fluentform .ff-el-group {
  margin-bottom: 13px !important;
}

.dgs-ai-ads-page .fluentform label,
.dgs-ai-ads-page .ff-el-input--label label,
.dgs-ai-ads-page .ff-el-form-check-label {
  color: #1f2430 !important;
  font-size: 14px !important;
  font-weight: 800 !important;
  margin-bottom: 6px !important;
  line-height: 1.3 !important;
}

.dgs-ai-ads-page .fluentform input[type="text"],
.dgs-ai-ads-page .fluentform input[type="email"],
.dgs-ai-ads-page .fluentform input[type="tel"],
.dgs-ai-ads-page .fluentform input[type="url"],
.dgs-ai-ads-page .fluentform input[type="number"],
.dgs-ai-ads-page .fluentform select,
.dgs-ai-ads-page .fluentform textarea {
  background: #fff !important;
  background-image: none !important;
  color: #111827 !important;
  caret-color: #111827 !important;
  border: 1px solid #d7dbe5 !important;
  box-shadow: none !important;
  border-radius: 13px !important;
  min-height: 48px !important;
  padding: 12px 14px !important;
  font-size: 16px !important;
  font-weight: 600 !important;
  line-height: 1.35 !important;
}

.dgs-ai-ads-page .fluentform textarea {
  min-height: 92px !important;
  resize: vertical !important;
}

.dgs-ai-ads-page .fluentform input::placeholder,
.dgs-ai-ads-page .fluentform textarea::placeholder {
  color: #8b92a1 !important;
  opacity: 1 !important;
}

.dgs-ai-ads-page .fluentform input:focus,
.dgs-ai-ads-page .fluentform select:focus,
.dgs-ai-ads-page .fluentform textarea:focus {
  border-color: #c43f7a !important;
  outline: none !important;
  box-shadow: 0 0 0 4px rgba(196,63,122,.12) !important;
}

.dgs-ai-ads-page .iti__flag-container,
.dgs-ai-ads-page .iti__selected-country,
.dgs-ai-ads-page .iti__selected-flag,
.dgs-ai-ads-page .iti__country-container,
.dgs-ai-ads-page .ff-el-phone .iti__flag-container {
  display: none !important;
  background: #fff !important;
  background-image: none !important;
  border: 0 !important;
  box-shadow: none !important;
}

.dgs-ai-ads-page .iti,
.dgs-ai-ads-page .ff-el-phone,
.dgs-ai-ads-page .ff-el-phone .iti {
  width: 100% !important;
}

.dgs-ai-ads-page .fluentform input[type="tel"],
.dgs-ai-ads-page .ff-el-phone input[type="tel"],
.dgs-ai-ads-page .iti input[type="tel"] {
  padding-left: 14px !important;
  color: #111827 !important;
  background: #fff !important;
  background-image: none !important;
  width: 100% !important;
}

.dgs-ai-ads-page .fluentform button,
.dgs-ai-ads-page .fluentform button[type="submit"],
.dgs-ai-ads-page .ff-btn-submit {
  width: 100% !important;
  min-height: 54px !important;
  border-radius: 999px !important;
  background: var(--dgs-gradient) !important;
  background-image: var(--dgs-gradient) !important;
  color: #fff !important;
  border: 0 !important;
  box-shadow: 0 16px 38px rgba(196,63,122,.22) !important;
  font-weight: 900 !important;
  font-size: 15px !important;
  letter-spacing: .2px !important;
  text-transform: none !important;
}

.dgs-ai-ads-page .fluentform button::before,
.dgs-ai-ads-page .fluentform button::after {
  content: none !important;
}

.dgs-ai-ads-page .text-danger,
.dgs-ai-ads-page .ff-el-is-error,
.dgs-ai-ads-page .error {
  color: #b42318 !important;
  font-size: 12px !important;
  font-weight: 700 !important;
}

.dgs-ai-clients {
  padding: 38px 0 !important;
  border-top: 1px solid rgba(20,17,31,.08) !important;
  border-bottom: 1px solid rgba(20,17,31,.08) !important;
  background: rgba(255,255,255,.45) !important;
}

.dgs-ai-strip-title {
  color: var(--dgs-soft) !important;
  text-align: center !important;
  margin: 0 0 20px !important;
  text-transform: uppercase !important;
  letter-spacing: 2.8px !important;
  font-size: 12px !important;
  font-weight: 900 !important;
}

.dgs-ai-logo-row {
  display: grid !important;
  grid-template-columns: repeat(5, minmax(0, 1fr)) !important;
  gap: 22px !important;
  max-width: 1480px !important;
  margin: 0 auto !important;
}

.dgs-ai-logo-chip {
  width: 100% !important;
  height: 112px !important;
  min-height: 112px !important;
  background: #fff !important;
  background-image: none !important;
  border: 1px solid rgba(17,24,39,.12) !important;
  border-radius: 22px !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  padding: 22px 26px !important;
  box-shadow: 0 18px 46px rgba(17,24,39,.07) !important;
  overflow: hidden !important;
}

.dgs-ai-logo-chip img {
  max-width: 86% !important;
  max-height: 62px !important;
  width: auto !important;
  height: auto !important;
  object-fit: contain !important;
  display: block !important;
}

.dgs-ai-card-grid {
  display: grid !important;
  grid-template-columns: repeat(3, minmax(0, 1fr)) !important;
  gap: 22px !important;
}

.dgs-ai-card {
  background: #fff !important;
  border: 1px solid var(--dgs-line) !important;
  border-radius: 28px !important;
  padding: clamp(24px, 2.2vw, 36px) !important;
  min-height: 240px !important;
  position: relative !important;
  overflow: hidden !important;
  box-shadow: var(--dgs-shadow) !important;
  transition: transform .25s ease, border-color .25s ease, box-shadow .25s ease !important;
}

.dgs-ai-card::before {
  content: "" !important;
  position: absolute !important;
  left: 0 !important;
  top: 0 !important;
  right: 0 !important;
  height: 4px !important;
  background: var(--dgs-gradient) !important;
  transform: scaleX(.34) !important;
  transform-origin: left !important;
  transition: transform .25s ease !important;
}

.dgs-ai-card:hover {
  transform: translateY(-7px) !important;
  border-color: rgba(196,63,122,.20) !important;
  box-shadow: var(--dgs-shadow-strong) !important;
}

.dgs-ai-card:hover::before {
  transform: scaleX(1) !important;
}

.dgs-ai-card b {
  display: inline-flex !important;
  width: 42px !important;
  height: 42px !important;
  border-radius: 999px !important;
  align-items: center !important;
  justify-content: center !important;
  background: rgba(196,63,122,.08) !important;
  color: var(--dgs-rose) !important;
  font-size: 13px !important;
  margin-bottom: 22px !important;
}

.dgs-ai-card h3,
.dgs-ai-card strong {
  display: block !important;
  color: var(--dgs-text) !important;
  font-size: clamp(22px, 2.1vw, 32px) !important;
  line-height: 1.12 !important;
  letter-spacing: -0.035em !important;
  margin: 0 0 14px !important;
  font-weight: 900 !important;
}

.dgs-ai-card p,
.dgs-ai-card span {
  display: block !important;
  color: var(--dgs-muted) !important;
  font-size: 15px !important;
  line-height: 1.72 !important;
  margin: 0 !important;
}

.dgs-ai-split {
  display: grid !important;
  grid-template-columns: minmax(0, .92fr) minmax(0, 1.08fr) !important;
  gap: 28px !important;
  align-items: stretch !important;
}

.dgs-ai-panel {
  background:
    radial-gradient(circle at 20% 20%, rgba(232,97,42,.10), transparent 32%),
    radial-gradient(circle at 76% 28%, rgba(98,71,176,.10), transparent 34%),
    #fff !important;
  border: 1px solid var(--dgs-line) !important;
  border-radius: 34px !important;
  padding: clamp(30px, 3vw, 52px) !important;
  box-shadow: var(--dgs-shadow) !important;
  overflow: hidden !important;
}

.dgs-ai-panel h2 {
  color: var(--dgs-text) !important;
  font-size: clamp(34px, 4.2vw, 64px) !important;
  line-height: 1.04 !important;
  letter-spacing: -0.055em !important;
  margin: 0 0 18px !important;
  font-weight: 900 !important;
}

.dgs-ai-panel p {
  color: var(--dgs-muted) !important;
  font-size: 17px !important;
  line-height: 1.78 !important;
  margin: 0 !important;
}

.dgs-ai-proof-list {
  display: grid !important;
  gap: 14px !important;
}

.dgs-ai-proof-item {
  background: #fff !important;
  border: 1px solid var(--dgs-line) !important;
  border-radius: 22px !important;
