  height: 42px;
  padding: 4px 6px;
  border-radius: 10px;
  background: #ffffff;
  overflow: hidden;
  flex-shrink: 0;
}

.dgs-footer-trust-logo-wrap img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: contain;
}

.dgs-footer-trust-copy {
  display: flex;
  flex-direction: column;
  justify-content: center;
  line-height: 1.15;
  text-align: left;
}

.dgs-footer-trust-title {
  font-size: 0.78rem;
  font-weight: 600;
  color: rgba(255, 255, 255, 0.96);
  letter-spacing: 0.2px;
  margin-bottom: 3px;
}

.dgs-footer-trust-stars {
  font-size: 0.82rem;
  font-weight: 500;
  color: #ff6b35;
  letter-spacing: 0.8px;
  margin-bottom: 3px;
}

.dgs-footer-trust-subtext {
  font-size: 0.68rem;
  font-weight: 300;
  color: rgba(255, 255, 255, 0.58);
  letter-spacing: 0.25px;
}

.dgs-footer-bottom {
  border-top: 1px solid rgba(255, 255, 255, 0.05);
  padding: clamp(20px, 3vw, 28px) 0;
  text-align: center;
}

.dgs-footer-copyright {
  font-size: clamp(0.75rem, 1.2vw, 0.85rem);
  font-weight: 300;
  color: rgba(255, 255, 255, 0.45);
  letter-spacing: 0.5px;
  margin-bottom: 10px;
}

.dgs-footer-copyright-gradient {
  background: linear-gradient(90deg, #00D4FF 0%, #FF00DC 50%, #FF6B35 100%);
  background-size: 200% 100%;
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  animation: gradientSlideFooter 8s linear infinite;
  font-weight: 400;
}

.dgs-footer-legal-links {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 20px;
  flex-wrap: wrap;
}

.dgs-footer-legal-link {
  font-size: clamp(0.75rem, 1.2vw, 0.82rem);
  font-weight: 300;
  color: rgba(255, 255, 255, 0.45);
  text-decoration: none;
  transition: all 0.3s ease;
  letter-spacing: 0.3px;
}

.dgs-footer-legal-link:hover {
  color: rgba(255, 255, 255, 0.85);
}

.dgs-footer-legal-divider {
  color: rgba(255, 255, 255, 0.25);
  font-weight: 300;
}

@keyframes gradientSlideFooter {
  0% { background-position: 0% 50%; }
  100% { background-position: 200% 50%; }
}

@media (max-width: 1100px) {
  .dgs-footer-grid {
    grid-template-columns: repeat(2, 1fr);
    gap: clamp(28px, 4vw, 35px);
  }

  .dgs-footer-trust-badges {
    justify-content: center;
  }

  .dgs-footer-logo-column {
    grid-column: 1 / -1;
    max-width: 100%;
    text-align: center;
    align-items: center;
  }

  .dgs-footer-logo {
    margin-left: auto;
    margin-right: auto;
  }

  .dgs-footer-social {
    justify-content: center;
  }

  .dgs-footer-ai-summary {
    text-align: center;
  }

  .dgs-footer-ai-icons {
    justify-content: center;
  }
}

@media (max-width: 968px) {
  .dgs-footer {
    padding: clamp(50px, 7vw, 70px) clamp(20px, 4vw, 30px) 0 !important;
  }

  .dgs-footer-grid {
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 30px;
  }

  .dgs-footer-column {
    text-align: center;
    align-items: center;
  }

  .dgs-footer-column-title::after {
    left: 50%;
    transform: translateX(-50%);
  }

  .dgs-footer-link::before {
    display: none;
  }

  .dgs-footer-link:hover {
    padding-left: 0;
  }

  .dgs-footer-contact-item {
    flex-direction: column;
    align-items: center;
    text-align: center;
    gap: 8px;
  }

  .dgs-footer-contact-item div {
    text-align: center;
  }

  .dgs-footer-contact-icon {
    margin-top: 0;
  }

  .dgs-footer-social {
    justify-content: center;
  }
}


  .dgs-footer-contact-column .dgs-footer-social {
    justify-content: center;
  }

  .dgs-footer-stalk-box {
    text-align: center;
  }

@media (max-width: 580px) {
  .dgs-footer {
    padding: 45px 20px 0 !important;
  }

  .dgs-footer-trust-badges {
    justify-content: center;
    gap: 10px;
    margin-bottom: 20px;
  }

  .dgs-footer-trust-badge {
    padding: 9px 12px 9px 9px;
    gap: 10px;
  }

  .dgs-footer-trust-logo-wrap {
    width: 68px;
    height: 40px;
  }

  .dgs-footer-trust-title {
    font-size: 0.74rem;
  }

  .dgs-footer-trust-stars {
    font-size: 0.78rem;
  }

  .dgs-footer-trust-subtext {
    font-size: 0.64rem;
  }

  .dgs-footer-grid {
    grid-template-columns: 1fr;
    gap: 28px;
  }

  .dgs-footer-legal-links {
    flex-direction: column;
    gap: 10px;
  }

  .dgs-footer-legal-divider {
    display: none;
  }



  .dgs-footer-ai-top {
    flex-direction: column;
    gap: 12px;
    margin-bottom: 30px;
    padding: 16px;
  }
  .dgs-footer-map-container iframe {
    height: 250px;
  }
}
